import React from 'react';
import { Outlet, NavLink } from 'react-router-dom';

const TrangChuQuanLy = () => {
    const menuItems = [
        { name: 'Quản lý thông báo', path: 'thong-bao', icon: '🔔' },
        { name: 'Quản lý cư dân', path: 'cu-dan', icon: '👤' },
        { name: 'Quản lý căn hộ', path: 'can-ho', icon: '🏠' },
        { name: 'Quản lý hoá đơn', path: 'hoa-don', icon: '📄' },
        { name: 'Quản lý yêu cầu bảo trì', path: 'bao-tri', icon: '🔧' },
        { name: 'Quản lý phương tiện', path: '🚗' },
        { name: 'Quản lý bãi đỗ xe', path: 'bai-do-xe', icon: '🅿️' },
        { name: 'Báo cáo & thống kê', path: 'thong-ke', icon: '📈' },
    ];

    return (
        <div style={styles.container}>
            {/* Lớp nền ảnh mờ tòa nhà */}
            <div className="dashboard-background" />

            {/* Sidebar thiết kế mềm mại hơn */}
            <div style={styles.sidebar}>
                <div style={styles.logo}>🏢 A&RMS</div>
                <nav style={styles.nav}>
                    {menuItems.map((item, index) => (
                        <NavLink 
                            key={index} 
                            to={`/dashboard-quan-ly/${item.path}`} 
                            style={({ isActive }) => ({
                                ...styles.navLink,
                                backgroundColor: isActive ? 'rgba(255, 255, 255, 0.1)' : 'transparent',
                                color: isActive ? '#fff' : '#a0aec0',
                                borderRadius: '12px', /* Bo góc item menu */
                                margin: '4px 15px'
                            })}
                        >
                            <span style={styles.icon}>{item.icon}</span> {item.name}
                        </NavLink>
                    ))}
                </nav>
            </div>

            {/* Vùng nội dung bên phải */}
            <div style={styles.content}>
                <header style={styles.header}>
                    <span style={{color: '#718096', fontSize: '14px'}}>Trang chủ / Danh sách quản lý</span>
                    <div style={styles.userIcon}>
                         <span style={styles.statusDot}></span> 👨‍💻 Admin System
                    </div>
                </header>

                <main style={styles.main}>
                    {/* Bọc Outlet trong một container để áp dụng class modern-card khi cần */}
                    <div className="fade-in">
                        <Outlet /> 
                    </div>
                </main>
            </div>
        </div>
    );
};

const styles = {
    container: { display: 'flex', height: '100vh', position: 'relative', overflow: 'hidden' },
    sidebar: { 
        width: '280px', 
        backgroundColor: '#1a202c', 
        color: '#fff', 
        display: 'flex', 
        flexDirection: 'column',
        zIndex: 10 
    },
    logo: { 
        padding: '30px 20px', 
        fontSize: '24px', 
        fontWeight: '800', 
        letterSpacing: '1px',
        textAlign: 'center',
        color: '#fff'
    },
    nav: { display: 'flex', flexDirection: 'column', marginTop: '10px' },
    navLink: { 
        padding: '12px 15px', 
        textDecoration: 'none', 
        fontSize: '14px', 
        fontWeight: '500',
        display: 'flex', 
        alignItems: 'center',
        transition: 'all 0.2s ease' 
    },
    icon: { marginRight: '12px', fontSize: '18px' },
    content: { flex: 1, display: 'flex', flexDirection: 'column', zIndex: 5 },
    header: { 
        height: '70px', 
        backgroundColor: 'rgba(255, 255, 255, 0.8)', 
        backdropFilter: 'blur(10px)', /* Hiệu ứng kính mờ cho header */
        display: 'flex', 
        alignItems: 'center', 
        justifyContent: 'space-between', 
        padding: '0 30px',
        borderBottom: '1px solid rgba(0,0,0,0.05)'
    },
    main: { padding: '30px', flex: 1, overflowY: 'auto' },
    userIcon: { 
        backgroundColor: '#fff', 
        padding: '8px 16px', 
        borderRadius: '30px', 
        boxShadow: '0 2px 10px rgba(0,0,0,0.05)',
        fontSize: '14px',
        fontWeight: '600',
        display: 'flex',
        alignItems: 'center',
        gap: '8px'
    },
    statusDot: { width: '8px', height: '8px', backgroundColor: '#48bb78', borderRadius: '50%' }
};

export default TrangChuQuanLy;
